onTextChanged:
{{(() => {
     // Typing invalidates whatever was found for the previous text. The search itself
     // is the "Търси" button beside this field (or Enter) - see 2026-09-19.
     if (NewDropoffLatHidden.text || NewDropoffLngHidden.text) {
       NewDropoffLatHidden.setValue("");
       NewDropoffLngHidden.setValue("");
     }
   })()}}

onSubmit:
{{(() => {
     const address = (NewDropoffAddressInput.text || "").trim();
     if (address.length < 4) {
       showAlert("Въведете адрес преди да търсите", "warning");
       return;
     }
     GeocodeNewDropoffAddress.run()
       .then(() => {
         if (GeocodeNewDropoffAddress.data?.results?.length > 0) {
           LocationManager.updateNewDropoffFromGeocode();
         } else {
           showAlert("Адресът не е намерен — проверете изписването", "warning");
         }
       })
       .catch(() => showAlert("Търсенето на адреса не мина. Опитайте пак.", "error"));
   })()}}
